prepared_pages AS (
  SELECT
    slug,
    jsonb_build_object('fr', title_fr, 'en', title_en, 'ar', title_ar) AS title,
    jsonb_build_object(
      'title', jsonb_build_object('fr', title_fr, 'en', title_en, 'ar', title_ar),
      'eyebrow', jsonb_build_object('fr', eyebrow_fr, 'en', eyebrow_en, 'ar', eyebrow_ar),
      'description', jsonb_build_object('fr', description_fr, 'en', description_en, 'ar', description_ar),
      'image', image,
      'kind', kind,
      'body', jsonb_build_array(jsonb_build_object('fr', body_fr, 'en', body_en, 'ar', body_ar))
    ) AS content
  FROM dynamic_pages
  UNION ALL
  SELECT
    slug,
    jsonb_build_object('fr', title_fr, 'en', title_en, 'ar', title_ar) AS title,
    jsonb_build_object(
      'title', jsonb_build_object('fr', title_fr, 'en', title_en, 'ar', title_ar),
      'eyebrow', jsonb_build_object('fr', 'Modele', 'en', 'Model', 'ar', 'نموذج'),
      'description', jsonb_build_object(
        'fr', title_fr || ' est une nacelle COMET configurable pour les chantiers marocains selon vehicule, hauteur, acces et contraintes terrain.',
        'en', title_en || ' is a COMET platform configurable for Moroccan work sites by vehicle, height, access, and site constraints.',
        'ar', title_ar || ' منصة COMET قابلة للتكوين للأوراش المغربية حسب المركبة والارتفاع والولوج وظروف الموقع.'
      ),
      'image', image,
      'kind', 'product',
      'body', jsonb_build_array(jsonb_build_object(
        'fr', 'COMET Morocco confirme compatibilite, delais, documentation technique et disponibilite commerciale pour votre projet.',
        'en', 'COMET Morocco confirms compatibility, lead time, technical documentation, and commercial availability for your project.',
        'ar', 'تؤكد COMET Morocco التوافق والآجال والوثائق التقنية والتوفر التجاري لمشروعكم.'
      )),
      'specs', jsonb_build_array(
        jsonb_build_object('label', jsonb_build_object('fr', 'Hauteur de travail', 'en', 'Working height', 'ar', 'ارتفاع العمل'), 'value', jsonb_build_object('fr', height, 'en', height, 'ar', height)),
        jsonb_build_object('label', jsonb_build_object('fr', 'Charge panier', 'en', 'Basket capacity', 'ar', 'حمولة السلة'), 'value', jsonb_build_object('fr', '200 kg - 2 personnes', 'en', '200 kg - 2 people', 'ar', '200 كلغ - شخصان')),
        jsonb_build_object('label', jsonb_build_object('fr', 'Marche', 'en', 'Market', 'ar', 'السوق'), 'value', jsonb_build_object('fr', 'Maroc', 'en', 'Morocco', 'ar', 'المغرب'))
      )
    ) AS content
  FROM model_pages
)
INSERT INTO public.site_pages (slug, title, content, is_published)
SELECT slug, title, content, true
FROM prepared_pages
ON CONFLICT (slug) DO UPDATE
SET title = EXCLUDED.title,
    content = public.site_pages.content || EXCLUDED.content,
    is_published = true,
    updated_at = now();
